function matchHeader(m){const h=m.teams?.home||{},a=m.teams?.away||{},s=status(m);txt("#detailCompetition",`${m.league?.country||"Football"} / ${m.league?.name||"Competition"}`);txt("#detailStatus",`${LIVE.has(s)?"LIVE · ":DONE.has(s)?"FINISHED · ":""}${liveTime(m)} · ${m.fixture?.venue?.name||""}`);for(const[id,t]of [["#homeName",h.name],["#awayName",a.name],["#homeLogo",h.logo],["#awayLogo",a.logo]]){const n=$(id);if(n.tagName==="IMG"){n.src=t||"";n.alt=t?"Team crest":"";n.hidden=!t;n.onerror=()=>n.hidden=true}else n.textContent=t||"Team"}txt("#fullScore",m.goals?.home==null?"– : –":`${m.goals.home} : ${m.goals.away}`);txt("#halfScore",m.score?.halftime?`HT ${m.score.halftime.home??"–"} : ${m.score.halftime.away??"–"}`:"");txt("#kickoffDetail",m.fixture?.date?new Date(m.fixture.date).toLocaleString():"");const b=$("#favoriteMatch");b.setAttribute("aria-pressed",String(favMatch(m)));b.textContent=favMatch(m)?"★ Following teams":"☆ Follow teams";renderEventTicker(state.stats.get(Number(m.fixture?.id))?.events||[])}
async function loadMatch(){if(!state.match)return;matchHeader(state.match);renderMatchPick(state.match);const id=Number(state.match.fixture?.id);if(state.stats.has(id)){renderDetail();return}$("#detailPanel").replaceChildren(el("div","loading","Loading provider statistics and match events…"));const q=new URLSearchParams({fixture:String(id),homeTeam:String(state.match.teams?.home?.id||""),awayTeam:String(state.match.teams?.away?.id||""),status:status(state.match)});try{const d=await edge(`fixture-statistics?${q}`,{headers:state.session?.access_token?{Authorization:`Bearer ${state.session.access_token}`}:{}});state.stats.set(id,d);matchHeader(state.match);renderDetail();renderInjuries(d.injuries||[])}catch(e){$("#detailPanel").replaceChildren(el("p","muted",`Match statistics unavailable: ${e.message}`));txt("#injuryList","Verified player availability is unavailable.")}}
function setTab(t){state.tab=t;$$('[data-detail-tab]').forEach(b=>b.classList.toggle("active",b.dataset.detailTab===t));renderDetail()}function renderDetail(){const host=$("#detailPanel"),m=state.match,d=state.stats.get(Number(m?.fixture?.id));host.replaceChildren();$$('[data-detail-tab]').forEach(b=>b.classList.toggle("active",b.dataset.detailTab===state.tab));if(!d){host.append(el("p","muted","Loading match data…"));return}if(state.tab==="overview")host.append(statsView(d,true),eventsView(d.events||[],true),formView(d,true));else if(state.tab==="stats")host.append(statsView(d,false));else if(state.tab==="events")host.append(eventsView(d.events||[],false));else if(state.tab==="form")host.append(formView(d,false));else host.append(analysisView(m,d))}
function statValue(v){return v==null||v===""?"—":String(v)}function statNum(v){return v==null?NaN:parseFloat(String(v).replace("%",""))}function statsView(d,compact){const box=el("section","stats-block");if(!compact)box.append(el("h3","","Match statistics"));const teams=d.response||[],types=[...new Set(teams.flatMap(t=>(t.statistics||[]).map(s=>s.type).filter(Boolean)))],priority=["Ball Possession","Total Shots","Shots on Goal","Shots on Target","Shots off Goal","Blocked Shots","Corner Kicks","Fouls","Offsides","Yellow Cards","Red Cards","Expected Goals","Passes %","Total passes","Goalkeeper Saves"];if(!types.length){box.append(el("p","muted","The provider has not published match statistics yet."));return box}types.sort((a,b)=>(priority.indexOf(a)<0?999:priority.indexOf(a))-(priority.indexOf(b)<0?999:priority.indexOf(b)));for(const name of compact?types.slice(0,7):types){const a=teams[0]?.statistics?.find(x=>x.type===name)?.value,b=teams[1]?.statistics?.find(x=>x.type===name)?.value,row=el("div","stat-row");row.append(el("span","",statValue(a)),el("strong","",name),el("span","",statValue(b)));box.append(row)}if(compact&&types.length>7){const b=el("button","text-action","See all statistics →");b.onclick=()=>setTab("stats");box.append(b)}if(d.upgradeRequired&&!state.vip){const note=el("div","vip-lock","Hub Plus unlocks advanced match statistics such as xG, plus ten-match form and verified availability.");if(!compact){const b=el("button","button button-outline","Explore Hub Plus");b.onclick=()=>showDialog("#vipDialog");note.append(b)}box.append(note)}return box}
function eventsView(events,compact){const box=el("section","events-block");if(!compact)box.append(el("h3","","Goals, cards & substitutions"));if(!events.length){box.append(el("p","muted","No provider events have been reported."));return box}for(const e of events.slice(0,compact?6:80)){const row=el("div","event-row");row.append(el("b","event-minute",`${e.time?.elapsed??"—"}${e.time?.elapsed?"′":""}`));let detail=`${e.team?.name||""} · ${e.player?.name||e.type||"Event"} · ${e.detail||e.type||""}`;if(e.type==="Goal"&&e.assist?.name)detail+=` · Assist: ${e.assist.name}`;row.append(el("span","",detail));box.append(row)}return box}
function formLetter(x,teamId){if(!x.goals||!x.teams)return"?";const home=Number(x.goals.home),away=Number(x.goals.away),own=Number(x.teams.home?.id)===Number(teamId),gf=own?home:away,ga=own?away:home;return gf>ga?"W":gf===ga?"D":"L"}function formView(d,compact){const box=el("section","form-block");if(!compact)box.append(el("h3","","Team form & head-to-head"));const m=state.match,home=m.teams?.home,away=m.teams?.away,groups=[{name:"Head-to-head · last 5",rows:d.headToHead||[],teamId:home?.id},{name:`${home?.name||"Home"} · last ${d.lastTen?.home?10:5}`,rows:d.lastTen?.home||d.lastFive?.home||[],teamId:home?.id},{name:`${away?.name||"Away"} · last ${d.lastTen?.away?10:5}`,rows:d.lastTen?.away||d.lastFive?.away||[],teamId:away?.id}];let found=false;for(const g of groups){if(!g.rows.length)continue;found=true;const part=el("div","form-group");part.append(el("strong","",g.name));if(g.name.startsWith("Head-to-head")){const w=g.rows.filter(x=>formLetter(x,home?.id)==="W").length,dr=g.rows.filter(x=>formLetter(x,home?.id)==="D").length,l=g.rows.filter(x=>formLetter(x,home?.id)==="L").length;part.append(el("small","muted",`${home?.name||"Home"}: ${w}W · ${dr}D · ${l}L`))}else{const atHome=g.rows.filter(x=>Number(x.teams?.home?.id)===Number(g.teamId)),awayGames=g.rows.filter(x=>Number(x.teams?.away?.id)===Number(g.teamId)),record=items=>`${items.filter(x=>formLetter(x,g.teamId)==="W").length}W-${items.filter(x=>formLetter(x,g.teamId)==="D").length}D-${items.filter(x=>formLetter(x,g.teamId)==="L").length}L`;part.append(el("small","muted",`Home ${record(atHome)} · Away ${record(awayGames)}`))}for(const x of g.rows.slice(0,compact?2:10)){const row=el("div","history-row");row.append(el("b","event-minute",formLetter(x,g.teamId)),el("span","",`${x.teams?.home?.name||"Home"} ${x.goals?.home??"—"}–${x.goals?.away??"—"} ${x.teams?.away?.name||"Away"} · ${x.fixture?.date?new Date(x.fixture.date).toLocaleDateString():""}`));part.append(row)}box.append(part)}if(!found)box.append(el("p","muted","Verified form and head-to-head data are unavailable."));if(d.upgradeRequired&&!state.vip){const note=el("div","vip-lock","Hub Plus members can view verified ten-match form and injury context."),b=el("button","button button-outline","Explore Hub Plus");b.onclick=()=>showDialog("#vipDialog");note.append(b);box.append(note)}return box}
function renderInjuries(items){const host=$("#injuryList");host.replaceChildren();if(!state.vip){host.append(el("p","muted","Verified injury and suspension data is included with Hub Plus."));return}if(!items.length){host.append(el("p","muted","No verified player availability data was returned for this match."));return}for(const x of items.slice(0,20))host.append(el("div","injury-row",`${x.player?.name||"Player"} · ${x.team?.name||"Team"} · ${x.type||"Unavailable"}${x.reason?` (${x.reason})`:""}`))}
function renderEventTicker(events){const host=$("#detailEventsTicker");host.replaceChildren();for(const e of events.filter(x=>["goal","card","subst"].some(k=>(x.type||"").toLowerCase().includes(k))).slice(0,8)){const text=e.type==="Goal"?`⚽ ${e.player?.name||"Goal"}${e.assist?.name?` · ${e.assist.name}`:""}`:e.type==="Card"?`🟨 ${e.player?.name||"Card"} ${e.detail||""}`:`↔ ${e.player?.name||"Change"}`;host.append(el("span","event-chip",`${e.time?.elapsed??""}′ ${text}`))}}
function analysisView(m,d){const box=el("section","analysis-block"),p=state.predictions.get(Number(m.fixture?.id)),a=predictionData(p).analysis;box.append(el("h3","","AI match analysis"));if(!p){box.append(el("p","muted","Request an AI forecast to build a report from provider evidence."));return box}box.append(el("p","",a.summary||p.rationale||"Summary unavailable."));if(!state.vip){box.append(marketsView(p),el("p","muted","Hub Plus unlocks detailed markets and the full AI report."));return box}const context=[["Recent performance",a.recentPerformance],["Attacking strength",a.attackingStrength],["Defensive strength",a.defensiveStrength],["Home / away context",a.homeAwayContext],["Availability",a.injuryContext]].filter(x=>x[1]);if(context.length){const grid=el("div","analysis-context");for(const[label,value]of context){const cell=el("div","");cell.append(el("small","",label),el("p","",value));grid.append(cell)}box.append(grid)}const factors=a.importantFactors||a.factors||[];if(factors.length){box.append(el("h4","","Important factors"));const ul=el("ul","analysis-factors");factors.forEach(x=>ul.append(el("li","",x)));box.append(ul)}box.append(el("p","muted",d.injuries?.length?`${d.injuries.length} verified availability item(s) were returned.`:"No verified injury or suspension details were supplied; no absences are assumed."),marketsView(p),el("p","disclaimer","Predictions are uncertain estimates, never guarantees."));return box}
function marketOdds(v){if(v?.yes!=null)return`Yes ${v.yes}% · No ${v.no}%`;if(v?.over!=null)return`Over ${v.over}% · Under ${v.under}%`;if(v?.probability!=null)return`Estimated probability ${v.probability}%`;if(v?.probabilities)return`Home ${v.probabilities.home}% · Draw ${v.probabilities.draw}% · Away ${v.probabilities.away}%`;return""}
function marketsView(p){const markets=predictionData(p).markets,box=el("div","market-grid"),items=[["Match winner",markets.matchWinner],["Double chance",markets.doubleChance],["Both teams to score",markets.btts],["Over/Under 1.5",markets.over15],["Over/Under 2.5",markets.over25],["Over/Under 3.5",markets.over35],["Correct score",markets.correctScore],["Half-time result",markets.halfTimeResult],["Half-time / full-time",markets.halfTimeFullTime],["Asian handicap",markets.asianHandicap]];for(const[n,v]of items)if(v){const x=el("div","prediction-market-detail");x.append(el("strong","",n),el("p","",v.selection||v.pick||"Unavailable"));const odds=marketOdds(v);if(odds)x.append(el("small","muted",odds));if(v.confidence!=null)x.append(el("small","confidence",`${v.confidence}% model confidence`));box.append(x)}if(!box.children.length)box.append(el("p","muted","This forecast has no expanded market data."));if(!state.vip){const lock=el("div","vip-lock","Hub Plus unlocks all markets and full match analysis."),b=el("button","button button-outline","Explore Hub Plus");b.onclick=()=>showDialog("#vipDialog");lock.append(b);box.append(lock)}return box}
function renderMatchPick(m){const host=$("#matchPrediction"),p=state.predictions.get(Number(m?.fixture?.id));host.replaceChildren();if(!p){host.append(el("p","muted","No forecast saved for this match."));return}const d=predictionData(p),w=d.markets.matchWinner;host.append(el("div","prediction-market-detail",`${w?.selection||p.prediction||"1X2 pick"} · ${p.confidence||"—"}% confidence`));const probs=w?.probabilities||d.root;if([probs.home,probs.draw,probs.away].some(v=>Number.isFinite(Number(v)))){const bars=el("div","probability-bars");for(const[k,l]of [["home","Home"],["draw","Draw"],["away","Away"]])if(Number.isFinite(Number(probs[k]))){const row=el("div","probability-bar"),track=el("div",""),fill=el("i","");fill.style.width=`${Math.min(100,Math.max(0,Number(probs[k])))}%`;track.append(fill);row.append(el("span","",l),track,el("b","",`${probs[k]}%`));bars.append(row)}host.append(bars)}if(d.analysis.summary||p.rationale)host.append(el("p","muted",d.analysis.summary||p.rationale));host.append(marketsView(p))}
function renderMatch(){if(!state.match)return;const f=state.match;txt("#detailCompetition",`${f.league?.country||"Football"} / ${f.league?.name||"Competition"}`);txt("#detailStatus",`${LIVE.has(status(f))?"LIVE · ":DONE.has(status(f))?"FINISHED · ":""}${liveTime(f)} · ${f.fixture?.venue?.name||""}`);for(const[id,t]of [["#homeName",f.teams?.home?.name],["#awayName",f.teams?.away?.name],["#homeLogo",f.teams?.home?.logo],["#awayLogo",f.teams?.away?.logo]]){const n=$(id);if(n.tagName==="IMG"){n.src=t||"";n.alt=t?"Team crest":"";n.hidden=!t}else n.textContent=t||"Team"}txt("#fullScore",f.goals?.home==null?"– : –":`${f.goals.home} : ${f.goals.away}`);txt("#halfScore",f.score?.halftime?`HT ${f.score.halftime.home??"–"} : ${f.score.halftime.away??"–"}`:"");txt("#kickoffDetail",f.fixture?.date?new Date(f.fixture.date).toLocaleString():"");$("#favoriteMatch").setAttribute("aria-pressed",String(favMatch(f)));$("#favoriteMatch").textContent=favMatch(f)?"★ Following teams":"☆ Follow teams";renderEventTicker(state.stats.get(Number(f.fixture?.id))?.events||[]);renderMatchPick(f)}async function loadMatch(){const m=state.match;if(!m)return;renderMatch();const id=Number(m.fixture?.id);if(state.stats.has(id)){renderDetail();return}$("#detailPanel").replaceChildren(el("div","loading","Loading official match statistics, events and form…"));const q=new URLSearchParams({fixture:String(id),homeTeam:String(m.teams?.home?.id||""),awayTeam:String(m.teams?.away?.id||""),status:status(m)});try{const d=await edge(`fixture-statistics?${q}`,{headers:state.session?.access_token?{Authorization:`Bearer ${state.session.access_token}`}:{}});state.stats.set(id,d);renderMatch();renderDetail();renderInjuries(d.injuries||[])}catch(e){$("#detailPanel").replaceChildren(el("p","muted",`Match detail service unavailable: ${e.message}`));txt("#injuryList","No verified availability data.")}}
function toggleSaved(p){const id=String(p.fixture_id);state.saved.has(id)?state.saved.delete(id):state.saved.add(id);persist("fah.saved",state.saved);syncMetadata();renderPredictions();renderDashboard();toast(state.saved.has(id)?"Saved to your dashboard.":"Removed from saved picks.")}
function renderDashboard(){const user=state.session?.user;if(!user){$("#accountDashboard").hidden=true;return}$("#accountDashboard").hidden=false;txt("#dashboardTitle",`Welcome, ${user.user_metadata?.full_name||user.email||"back"}`);const fav=$("#favoriteTeams");fav.replaceChildren();const teams=new Map();for(const m of state.fixtures)for(const t of[m.teams?.home,m.teams?.away])if(t&&(state.favorites.has(String(t.id))||state.favorites.has(`name:${norm(t.name)}`)))teams.set(String(t.id||t.name),t.name);if(!teams.size)fav.append(el("p","muted","Tap ☆ on a match to follow the teams."));for(const[id,n]of teams){const r=el("div","dashboard-team",n),b=el("button","","Remove");b.onclick=()=>{state.favorites.delete(id);state.favorites.delete(`name:${norm(n)}`);persist("fah.favorites",state.favorites);renderDashboard();renderScores();syncMetadata()};r.append(b);fav.append(r)}const saved=$("#savedPredictions");saved.replaceChildren();const picks=[...state.saved].map(id=>state.predictions.get(Number(id))).filter(Boolean);if(!picks.length)saved.append(el("p","muted","Save an AI forecast to keep it here."));for(const p of picks)saved.append(el("div","saved-prediction-row",`${p.home_team} vs ${p.away_team} · ${p.prediction||"AI forecast"}`));txt("#vipAccessLabel",state.vip?"Hub Plus active":"Free access");txt("#accountStatus",state.vip?"Premium access is active.":"Live scores and basic stats are available free.")}
async function syncMetadata(){if(!state.session?.access_token)return;try{const user=await auth("user",{data:{favorite_teams:[...state.favorites],saved_prediction_ids:[...state.saved]}},"PUT");state.session.user=user;localStorage.setItem("fah.session",JSON.stringify(state.session))}catch(e){console.info("Preferences kept on this device",e.message)}}
async function currentUser(){if(!state.session?.access_token)return null;try{const user=await auth("user",null,"GET");state.session.user=user;localStorage.setItem("fah.session",JSON.stringify(state.session));return user}catch{if(state.session?.refresh_token){try{const d=await json(`${CFG.url}/auth/v1/token?grant_type=refresh_token`,{method:"POST",headers:{apikey:CFG.key,"Content-Type":"application/json"},body:JSON.stringify({refresh_token:state.session.refresh_token})});state.session=d;localStorage.setItem("fah.session",JSON.stringify(d));return d.user||null}catch{}}localStorage.removeItem("fah.session");state.session=null;return null}}
async function refreshAccount(){const user=await currentUser();state.vip=false;state.admin=false;$("#adminOpen").hidden=true;if(!user){$("#accountOpen").textContent="Sign in";renderDashboard();return}$("#accountOpen").textContent="Dashboard";if(Array.isArray(user.user_metadata?.favorite_teams))state.favorites=new Set(user.user_metadata.favorite_teams.map(String));if(Array.isArray(user.user_metadata?.saved_prediction_ids))state.saved=new Set(user.user_metadata.saved_prediction_ids.map(String));persist("fah.favorites",state.favorites);persist("fah.saved",state.saved);try{const q=new URLSearchParams({select:"plan,submitted_at,approved_at",user_id:`eq.${user.id}`,status:"eq.approved"}),payments=await rest("vip_payments",q),dur={daily:1,weekly:7,monthly:30};state.vip=(payments||[]).some(p=>{const at=Date.parse(p.approved_at||p.submitted_at||"");return dur[p.plan]&&Number.isFinite(at)&&at+dur[p.plan]*86400000>Date.now()})}catch{}try{const rows=await rest("admin_users",new URLSearchParams({select:"user_id",user_id:`eq.${user.id}`,limit:"1"}));state.admin=Boolean(rows?.length)}catch{}$("#adminOpen").hidden=!state.admin;const ids=[...state.saved].map(Number).filter(Number.isSafeInteger).slice(0,30);if(ids.length){try{const data=await edge(`football-predictions?fixtures=${ids.join("-")}`,{headers:{Authorization:`Bearer ${state.session.access_token}`}});for(const p of data.predictions||[])state.predictions.set(Number(p.fixture_id),p)}catch{}}if(state.admin)await loadLeagueSettings();renderDashboard()}
function showAuth(){txt("#accountTitle","Sign in to FOOTBALL AI HUB");txt("#accountIntro","Save forecasts and follow favourite teams.");$("#authForm").hidden=false;txt("#authMessage","");showDialog("#accountDialog")}
async function submitAuth(e){e.preventDefault();const b=$("#authSubmit");b.disabled=true;const old=b.textContent;b.textContent="Please wait…";try{const email=$("#emailInput").value.trim(),password=$("#passwordInput").value,d=state.signup?await json(`${CFG.url}/auth/v1/signup`,{method:"POST",headers:{apikey:CFG.key,"Content-Type":"application/json"},body:JSON.stringify({email,password})}):await json(`${CFG.url}/auth/v1/token?grant_type=password`,{method:"POST",headers:{apikey:CFG.key,"Content-Type":"application/json"},body:JSON.stringify({email,password})});if(!d.access_token){txt("#authMessage","Account created. Check your email to confirm, then sign in.");return}state.session=d;localStorage.setItem("fah.session",JSON.stringify(d));await refreshAccount();$("#accountDialog").close();toast("Signed in to FOOTBALL AI HUB.")}catch(error){txt("#authMessage",error.message)}finally{b.disabled=false;b.textContent=old}}
async function payment(e){e.preventDefault();if(!state.session?.user){$("#vipDialog").close();showAuth();txt("#authMessage","Sign in before submitting payment details.");return}const plan=$("#planInput").value,amount={daily:300,weekly:1000,monthly:2500}[plan],code=$("#mpesaInput").value.trim().toUpperCase(),phone=$("#phoneInput").value.trim();if(!/^[A-Z0-9]{8,20}$/.test(code)||!/^(?:\+?254|0)7\d{8}$/.test(phone)){txt("#paymentStatus","Check the transaction code and Kenyan phone number.");return}try{await rest("vip_payments",new URLSearchParams(),{method:"POST",prefer:"return=minimal",body:{user_id:state.session.user.id,email:state.session.user.email,phone_number:phone,plan,amount,mpesa_code:code,status:"pending"}});txt("#paymentStatus","Submitted. Hub Plus starts after administrator verification.");e.currentTarget.reset()}catch(error){txt("#paymentStatus",error.message)}}
async function loadNews(){try{const d=await edge("football-news");state.news=Array.isArray(d.items)?d.items:[];renderNews()}catch(e){console.info("News feed unavailable",e.message);renderNews(false)}}function renderNews(unavailable=false){const host=$("#newsGrid"),rail=$("#railNews");host.replaceChildren();rail.replaceChildren();const items=state.news.filter(x=>x.url&&/^https:\/\/(www\.)?bbc\.(co\.uk|com)\//i.test(x.url));if(!items.length){host.append(el("div","empty-panel",unavailable?"Football news feed unavailable. Headlines are never fabricated.":"No verified headlines are available right now."));rail.append(el("p","muted","No verified news right now."));return}for(const item of items.slice(0,9)){const card=el("article","news-card"),link=document.createElement("a");link.href=item.url;link.target="_blank";link.rel="noopener noreferrer";link.append(el("h3","",item.title));card.append(link);if(item.summary)card.append(el("p","",item.summary));card.append(el("small","",`${item.source||"BBC Sport"} · ${item.published?new Date(item.published).toLocaleString():"Latest"}`));host.append(card);if(rail.children.length<4){const mini=el("article","news-mini"),a=document.createElement("a");a.href=item.url;a.target="_blank";a.rel="noopener noreferrer";a.textContent=item.title;mini.append(a,el("small","",item.source||"BBC Sport"));rail.append(mini)}}}
async function notifications(){if(!("Notification"in window)){toast("This browser does not support notifications.",true);return}if(!isSecureContext){toast("Notifications need HTTPS or localhost.",true);return}const p=await Notification.requestPermission();toast(p==="granted"?"Match notifications enabled.":"Notification access was not granted.",p!=="granted");if(p==="granted")checkReminders()}function remindMatch(){if(!state.match)return;if(!("Notification"in window)||Notification.permission!=="granted"){notifications();return}const id=String(state.match.fixture?.id);if(state.reminders.has(id))state.reminders.delete(id);else state.reminders.add(id);persist("fah.reminders",state.reminders);$("#remindMatchButton").textContent=state.reminders.has(id)?"◷ Reminder set":"◷ Remind me";toast(state.reminders.has(id)?"Reminder saved on this device.":"Reminder removed.");checkReminders()}function checkReminders(){if(!("Notification"in window)||Notification.permission!=="granted")return;for(const id of state.reminders){const m=state.fixtures.find(x=>String(x.fixture?.id)===id),at=Date.parse(m?.fixture?.date||"");if(m&&at>Date.now()&&at<Date.now()+36*3600e3&&Date.now()>=at-15*60e3&&!state.seen.has(id)){new Notification("Kick-off soon",{body:`${m.teams?.home?.name} vs ${m.teams?.away?.name}`,tag:`fah-${id}`});state.seen.add(id);persist("fah.seen",state.seen)}}}
async function adminPayments(){const h=$("#adminPayments");h.textContent="Loading reviews…";try{const rows=await rest("vip_payments",new URLSearchParams({select:"id,email,plan,amount,mpesa_code,status",order:"submitted_at.desc",limit:"40"}));h.replaceChildren();for(const r of rows||[]){const line=el("div","admin-item",`${r.email} · ${r.plan} · KSh ${r.amount} · ${r.status}`);if(r.status==="pending")for(const status of["approved","rejected"]){const b=el("button","",status);b.onclick=async()=>{try{await rest("vip_payments",new URLSearchParams({id:`eq.${r.id}`}),{method:"PATCH",prefer:"return=minimal",body:{status}});adminPayments()}catch(e){txt("#adminMessage",e.message)}};line.append(b)}h.append(line)}if(!rows?.length)h.textContent="No payment submissions."}catch(e){h.textContent=e.message}}
async function adminPredictions(){const h=$("#adminPredictions");h.textContent="Loading saved forecasts…";try{const rows=await rest("ai_match_predictions",new URLSearchParams({select:"fixture_id,home_team,away_team,prediction",order:"kickoff_at.desc",limit:"25"}));h.replaceChildren();for(const p of rows||[]){const line=el("div","admin-item"),input=document.createElement("input");input.value=p.prediction||"";input.setAttribute("aria-label",`Edit ${p.home_team} vs ${p.away_team}`);const b=el("button","","Save");b.onclick=async()=>{try{await rest("ai_match_predictions",new URLSearchParams({fixture_id:`eq.${p.fixture_id}`}),{method:"PATCH",prefer:"return=minimal",body:{prediction:input.value.slice(0,240),admin_overridden:true,updated_at:new Date().toISOString()}});txt("#adminMessage","Prediction updated.")}catch(e){txt("#adminMessage",e.message)}};line.append(el("span","",`${p.home_team} vs ${p.away_team}`),input,b);h.append(line)}if(!rows?.length)h.textContent="No predictions available."}catch(e){h.textContent=e.message}}
async function adminUsers(){if(!state.admin)return;try{const d=await edge("football-admin",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${state.session.access_token}`},body:JSON.stringify({action:"users"})});txt("#adminUserCount",d.total??d.users?.length??"—");const h=$("#adminUsers");if(!h)return;h.replaceChildren();for(const u of d.users||[]){const line=el("div","admin-item",`${u.email||"No email"} · ${new Date(u.created_at).toLocaleDateString()} · ${u.banned_until?"Suspended":"Active"}`),b=el("button","",u.banned_until?"Restore":"Suspend 24h");b.onclick=async()=>{if(!confirm(`${u.banned_until?"Restore":"Suspend"} ${u.email}?`))return;try{await edge("football-admin",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${state.session.access_token}`},body:JSON.stringify({action:"set_ban",userId:u.id,banDuration:u.banned_until?"none":"24h"})});adminUsers()}catch(e){txt("#adminMessage",e.message)}};line.append(b);h.append(line)}}catch(e){txt("#adminUserCount","Unavailable");console.info("User management function not deployed",e.message)}}
async function openAdmin(){if(!state.admin){toast("Administrator access required.",true);return}$("#adminFixtureCount").textContent=state.fixtures.length;$("#adminLiveCount").textContent=state.fixtures.filter(m=>LIVE.has(status(m))).length;showDialog("#adminDialog");await Promise.all([adminPayments(),adminPredictions(),adminUsers(),adminLeagues()])}async function publishTip(e){e.preventDefault();const d=new FormData(e.currentTarget),vip=d.get("is_vip")==="true",daily=d.get("is_bet_of_day")==="on";if(daily&&!vip){txt("#adminMessage","The Bet of the Day must be a VIP pick.");return}try{if(daily)await rest("matches",new URLSearchParams({is_bet_of_day:"eq.true"}),{method:"PATCH",prefer:"return=minimal",body:{is_bet_of_day:false}});await rest("matches",new URLSearchParams(),{method:"POST",prefer:"return=minimal",body:{home_team:String(d.get("home_team")).trim(),away_team:String(d.get("away_team")).trim(),competition:String(d.get("competition")).trim(),prediction:String(d.get("prediction")).trim(),odds:Number(d.get("odds")),is_vip:vip,is_bet_of_day:daily}});e.currentTarget.reset();txt("#adminMessage","Prediction published.");await loadTips()}catch(error){txt("#adminMessage",error.message)}}
