 $("#dateInput").value=state.date;$("#dateInput").onchange=loadFixtures;$("#prevDay").onclick=()=>shift(-1);$("#nextDay").onclick=()=>shift(1);$("#todayButton").onclick=()=>{$("#dateInput").value=today();loadFixtures()};$("#refreshButton").onclick=loadFixtures;$("#searchInput").oninput=e=>{state.query=e.target.value;renderScores()};$("#timeFilter").onchange=e=>{state.time=e.target.value;renderScores()};$("#topFiveButton").onclick=e=>{state.topOnly=!state.topOnly;e.currentTarget.setAttribute("aria-pressed",String(state.topOnly));renderScores()};$("#clearFilters").onclick=()=>{Object.assign(state,{country:"",league:"",query:"",time:"",status:"all",topOnly:false});$("#searchInput").value="";$("#topFiveButton").setAttribute("aria-pressed","false");$$('[data-status]').forEach(b=>b.classList.toggle("active",b.dataset.status==="all"));renderScores()};$$('[data-status]').forEach(b=>b.onclick=()=>{state.status=b.dataset.status;$$('[data-status]').forEach(x=>x.classList.toggle("active",x===b));renderScores()});$("#loadMore").onclick=()=>{state.limit+=30;renderMatches()};$("#leagueSearch").oninput=renderDirectory;
