function miniMarkets(markets){const box=el("div","mini-markets"),items=[["BTTS",markets.btts],["O1.5",markets.over15],["O2.5",markets.over25],["O3.5",markets.over35],["HT",markets.halfTimeResult],["HT/FT",markets.halfTimeFullTime]];for(const[name,item]of items)if(item){const detail=item.yes!=null?`Y ${item.yes}% / N ${item.no}%`:item.over!=null?`${item.over}% / ${item.under}%`:item.probability!=null?`${item.probability}%`:item.probabilities?`${item.probabilities.home}/${item.probabilities.draw}/${item.probabilities.away}`:item.selection;const chip=el("span","mini-market-chip");chip.append(el("small","",name),el("b","",`${item.selection||"Pick"} · ${detail}`));box.append(chip)}return box}
