async function adminLeagues(){const host=$("#adminLeagues");if(!host)return;host.replaceChildren();const leagues=new Map();for(const m of state.fixtures){if(!m.league?.id)continue;leagues.set(Number(m.league.id),{id:Number(m.league.id),name:m.league.name||"Competition",country:m.league.country||"International"})}if(!leagues.size){host.textContent="No fixture competitions are available to manage today.";return}for(const l of leagues.values()){const saved=state.leagueSettings.get(l.id),row=el("label","admin-item"),input=document.createElement("input");input.type="checkbox";input.checked=saved?.is_enabled!==false;input.setAttribute("aria-label",`Show ${l.name} to visitors`);input.onchange=async()=>{try{await rest("football_hub_league_settings",new URLSearchParams({on_conflict:"league_id"}),{method:"POST",prefer:"resolution=merge-duplicates,return=minimal",body:{league_id:l.id,league_name:l.name,country:l.country,is_enabled:input.checked}});state.leagueSettings.set(l.id,{...(saved||{}),...l,is_enabled:input.checked});renderScores();renderDirectory();txt("#adminMessage",`${l.name} visibility updated.`)}catch(e){input.checked=!input.checked;txt("#adminMessage",`League settings need the SQL migration: ${e.message}`)}};row.append(input,el("span","",`${l.country} · ${l.name}`));host.append(row)}}

